import java.util.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Read-only CFG including exception edges; removing the accepted node must disconnect calculation entry. */
public final class SourceAreaClassSelectionFlow {
 static boolean dominates(MethodNode m,AbstractInsnNode accepted,AbstractInsnNode target){var nodes=m.instructions.toArray();var index=new IdentityHashMap<AbstractInsnNode,Integer>();for(int i=0;i<nodes.length;i++)index.put(nodes[i],i);int stop=index.get(accepted),dest=index.get(target);var visited=new BitSet(nodes.length);var queue=new ArrayDeque<Integer>();if(stop!=0)queue.add(0);while(!queue.isEmpty()){int i=queue.remove();if(i==stop||visited.get(i))continue;if(i==dest)return false;visited.set(i);var n=nodes[i];int op=n.getOpcode();var edges=new ArrayList<Integer>();if(n instanceof JumpInsnNode j){edges.add(index.get(j.label));if(op!=GOTO&&i+1<nodes.length)edges.add(i+1);}else if(n instanceof TableSwitchInsnNode s){edges.add(index.get(s.dflt));for(var l:s.labels)edges.add(index.get(l));}else if(n instanceof LookupSwitchInsnNode s){edges.add(index.get(s.dflt));for(var l:s.labels)edges.add(index.get(l));}else if(op!=ATHROW&&(op<IRETURN||op>RETURN)&&i+1<nodes.length)edges.add(i+1);for(var t:m.tryCatchBlocks)if(i>=index.get(t.start)&&i<index.get(t.end))edges.add(index.get(t.handler));for(int e:edges)if(!visited.get(e)&&e!=stop)queue.add(e);}return true;}
}
